-- ADCT, comentários didáticos, lote 5 (arts. 42 a 51), só a partir do texto no banco. Já aplicado.
update legislacao set contexto = $c$Recursos para irrigação$c$, aplicacao_pratica = $a$Determina que, durante quarenta anos, a União aplique dos recursos destinados à irrigação vinte por cento na Região Centro-Oeste (I) e cinquenta por cento na Região Nordeste, preferencialmente no Semiárido (II). O parágrafo único destina, dos percentuais dos incisos I e II, no mínimo cinquenta por cento a projetos de irrigação que beneficiem agricultores familiares que atendam aos requisitos da legislação específica.$a$ where codigo='adct' and numero=42 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
update legislacao set contexto = $c$Títulos minerários sem trabalhos iniciados$c$, aplicacao_pratica = $a$Previu que, na data da promulgação da lei que disciplinasse a pesquisa e a lavra de recursos e jazidas minerais, ou em um ano da promulgação da Constituição, ficassem sem efeito as autorizações, concessões e demais títulos de direitos minerários cujos trabalhos de pesquisa ou lavra não houvessem sido comprovadamente iniciados nos prazos legais ou estivessem inativos. Norma transitória de aplicação já exaurida quanto ao prazo.$a$ where codigo='adct' and numero=43 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
update legislacao set contexto = $c$Empresas brasileiras de mineração e energia hidráulica$c$, aplicacao_pratica = $a$Concedeu às atuais empresas brasileiras titulares de autorização de pesquisa, concessão de lavra de recursos minerais e aproveitamento de potenciais de energia hidráulica quatro anos, a partir da promulgação, para cumprir os requisitos do art. 176, § 1º. O § 1º dispensou desse cumprimento, ressalvadas as disposições de interesse nacional, as empresas cujo produto da lavra e beneficiamento fosse destinado à industrialização no território nacional no prazo de quatro anos, o § 2º dispensou também as titulares de concessão de energia hidráulica para uso em seu processo de industrialização e o § 3º condicionou as autorizações, concessões e potenciais das empresas do § 1º à utilização da energia e do produto da lavra em seus processos industriais.$a$ where codigo='adct' and numero=44 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
update legislacao set contexto = $c$Refinarias e contratos de risco anteriores$c$, aplicacao_pratica = $a$Excluiu do monopólio do art. 177, II, as refinarias em funcionamento no País amparadas pelo art. 43 e nas condições do art. 45 da Lei nº 2.004/1953. O parágrafo único ressalvou da vedação do art. 177, § 1º, os contratos de risco feitos com a Petróleo Brasileiro S.A. (Petrobrás) para pesquisa de petróleo que estivessem em vigor na data da promulgação.$a$ where codigo='adct' and numero=45 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
update legislacao set contexto = $c$Correção monetária de créditos em intervenção e liquidação$c$, aplicacao_pratica = $a$Sujeita à correção monetária, desde o vencimento até o efetivo pagamento, sem interrupção ou suspensão, os créditos junto a entidades submetidas a intervenção ou liquidação extrajudicial, mesmo quando convertidas em falência. O parágrafo único estende a regra às operações posteriores à decretação dos regimes (I), a operações de empréstimo, financiamento, assistência de liquidez e semelhantes (II), aos créditos anteriores à promulgação (III) e aos créditos de entidades da administração pública anteriores à promulgação não liquidados até 1º de janeiro de 1988 (IV).$a$ where codigo='adct' and numero=46 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
update legislacao set contexto = $c$Isenção de correção monetária em empréstimos antigos$c$, aplicacao_pratica = $a$Afastou a correção monetária na liquidação de débitos decorrentes de empréstimos bancários concedidos a micro e pequenos empresários entre 28 de fevereiro de 1986 e 28 de fevereiro de 1987 (I) e a mini, pequenos e médios produtores rurais entre 28 de fevereiro de 1986 e 31 de dezembro de 1987, em crédito rural (II). O § 1º definiu microempresas e pequenas empresas por receita anual em Obrigações do Tesouro Nacional, o § 2º remeteu a classificação do produtor rural às normas de crédito rural da época, o § 3º condicionou a isenção a cinco requisitos (I a V), entre eles a liquidação em noventa dias da promulgação, o § 4º excluiu débitos quitados e devedores constituintes, o § 5º tratou do ajuste de contratos com prazo posterior, e os §§ 6º e 7º trataram do ônus da concessão do benefício. Norma transitória de aplicação já exaurida quanto ao prazo de liquidação.$a$ where codigo='adct' and numero=47 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
update legislacao set contexto = $c$Código de defesa do consumidor$c$, aplicacao_pratica = $a$Determinou que o Congresso Nacional elaborasse, dentro de cento e vinte dias da promulgação da Constituição, código de defesa do consumidor.$a$ where codigo='adct' and numero=48 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
update legislacao set contexto = $c$Enfiteuse em imóveis urbanos$c$, aplicacao_pratica = $a$Determina que a lei disponha sobre a enfiteuse em imóveis urbanos, facultando aos foreiros, no caso de extinção, a remição dos aforamentos mediante aquisição do domínio direto, conforme os contratos. O § 1º adota, na falta de cláusula contratual, os critérios da legislação especial dos imóveis da União, o § 2º assegura os direitos dos atuais ocupantes inscritos mediante outra modalidade de contrato, o § 3º mantém a enfiteuse nos terrenos de marinha e seus acrescidos situados na faixa de segurança, a partir da orla marítima, e o § 4º impõe ao antigo titular do domínio direto, remido o foro, entregar a documentação ao registro de imóveis competente em noventa dias, sob pena de responsabilidade.$a$ where codigo='adct' and numero=49 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
update legislacao set contexto = $c$Lei agrícola$c$, aplicacao_pratica = $a$Determinou que lei agrícola, a ser promulgada em um ano, dispusesse sobre os objetivos e instrumentos de política agrícola, prioridades, planejamento de safras, comercialização, abastecimento interno, mercado externo e instituição de crédito fundiário. Norma transitória de aplicação já exaurida quanto ao prazo.$a$ where codigo='adct' and numero=50 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
update legislacao set contexto = $c$Revisão de doações e vendas de terras públicas$c$, aplicacao_pratica = $a$Determinou que o Congresso Nacional revisse, por Comissão mista, em três anos da promulgação, as doações, vendas e concessões de terras públicas com área superior a três mil hectares realizadas de 1º de janeiro de 1962 a 31 de dezembro de 1987. O § 1º limitou a revisão das vendas ao critério de legalidade, o § 2º fixou, para concessões e doações, os critérios de legalidade e conveniência do interesse público e o § 3º previu a reversão das terras ao patrimônio da União, dos Estados, do Distrito Federal ou dos Municípios, comprovada a ilegalidade ou havendo interesse público.$a$ where codigo='adct' and numero=51 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
